 function render(a){current=a;notice('');const r=a.risk;const color=r.score===null?'var(--muted)':r.score>=70?'var(--danger)':r.score>30?'var(--amber)':'#2c6735';$('analysis-dashboard').hidden=false;$('report-target').textContent=a.target;$('report-id').textContent=(root?.report_id||'').slice(0,12);$('report-time').textContent=new Date(a.timestamp).toLocaleString('en-GB');$('mode-notice').textContent=a.kind==='file'?'FILE ANALYSIS — bounded static inspection ran on this server. The file was not executed. Reputation queries use hashes; extracted URLs are separate checks.':a.kind==='imap'?'EMAIL ANALYSIS — sender headers, body links and attachments are kept in message context. Raw authentication headers are not independently trusted.':'URL ANALYSIS — local URL checks and configured external intelligence. The destination page is not opened.';$('risk-number').textContent=r.score===null?'—':r.score;$('risk-level').textContent=r.level;$('risk-level').style.color=color;$('score-ring').style.setProperty('--score',r.score||0);$('score-ring').style.setProperty('--risk-color',color);$('risk-description').textContent=r.score===null?'No meaningful numerical score could be established.':r.score>30?'Observed indicators warrant investigation. This is not a phishing probability.':'Few or no weighted indicators were observed in completed checks. Safety is not established.';$('finding-number').textContent=a.findings.length;const done=a.checks.filter(c=>c.status==='complete').length;$('coverage-number').textContent=done+'/'+a.checks.length;$('coverage-label').textContent='Checks complete · '+a.checks.filter(c=>c.status==='partial').length+' partial';
 const reasoning=caseReasoning(a);$('assessment-title').textContent=reasoning.title;$('assessment-basis').textContent=reasoning.basis;$('assessment-quality').textContent=a.providers.some(p=>p.state==='completed'&&p.hasEvidence)?'Local + reputation evidence':'Local inspection';$('assessment-next').textContent=reasoning.next;
 const groups=new Map();for(const code of r.codes){if(RULES[code]){const rule=RULES[code];groups.set(rule.group,(groups.get(rule.group)||0)+rule.points);}}if(r.reputation)groups.set(a.linkedReputationPoints?'Strongest reputation / linked URL':'Strongest reputation signal',r.reputation);$('contribution-chart').replaceChildren();if(!groups.size)$('contribution-chart').append(el('p',r.score===null?'Score withheld.':'No weighted indicators observed.','fineprint'));for(const [label,n] of groups){const row=el('div',undefined,'contribution-row'),track=el('div',undefined,'contribution-track'),fill=el('div',undefined,'contribution-fill');fill.style.width=Math.min(100,n)+'%';fill.style.background=color;track.append(fill);row.append(el('span',label),track,el('b','+'+n));$('contribution-chart').append(row);}if(r.localRaw>70)$('contribution-chart').append(el('p','Local indicators: '+r.localRaw+' raw → capped at 70.','fineprint'));
 $('checks-list').replaceChildren();for(const c of a.checks){const row=el('div',undefined,'check-row'),text=el('div',c.label);if(c.detail)text.append(el('p',c.detail,'fineprint'));row.append(text,el('span',c.status.toUpperCase(),'status-pill status-'+c.status));$('checks-list').append(row);}
 $('evidence-body').replaceChildren();for(const f of a.findings){const tr=el('tr');tr.append(el('td',f.label),el('td',f.evidence),el('td','+'+f.points+'¹'),el('td',f.source));$('evidence-body').append(tr);}$('no-evidence').hidden=!!a.findings.length;$('evidence-caption').textContent=a.findings.length+' OBSERVATIONS · ¹ EACH RULE COUNTED ONCE';$('indicator-list').replaceChildren();if(a.sha256){const row=el('div',undefined,'ioc-item');row.append(el('span','SHA-256'),el('div',a.sha256));$('indicator-list').append(row);}a.links.slice(0,15).forEach(u=>{const row=el('div',undefined,'ioc-item');row.append(el('span','URL'),el('div',defang(u)));$('indicator-list').append(row);});if(!a.links.length&&!a.sha256)$('indicator-list').append(el('p','No supported indicators extracted.','fineprint'));
 $('source-status').replaceChildren();for(const p of a.providers){const tr=el('tr',undefined,'source-row'),status=el('td'),desc=el('td',p.detail);status.append(el('span',p.status,'status-pill'));const stamps=[p.checked_at?'Checked: '+new Date(p.checked_at).toLocaleString('en-GB'):'',p.cached?'Cached result':'',p.last_analysis_date?'Report: '+new Date(p.last_analysis_date*1000).toLocaleString('en-GB'):''].filter(Boolean).join(' · ');if(stamps)desc.append(el('p',stamps,'fineprint'));tr.append(el('td',p.name),el('td',p.scope),status,desc);$('source-status').append(tr);}$('source-count').textContent=a.providers.filter(p=>p.state==='completed').length+' / '+a.providers.length+' applicable source response(s) received';
 const engines=a.providers.flatMap(p=>(p.engines||[]).map(e=>({...e,provider:p.name})));$('engine-panel').hidden=!engines.length;$('engine-rows').replaceChildren();engines.forEach(e=>{const tr=el('tr');tr.append(el('td',e.engine_name),el('td',e.category),el('td',e.result||'No detection label'),el('td',e.engine_update||'Not supplied'));$('engine-rows').append(tr);});context(a);setExposure('received');$('ai-details').hidden=!root?.ai_summary;$('ai-output').textContent=root?.ai_summary||'';$('generate-ai').disabled=!!root?._from_history;$('ai-status').textContent=root?._from_history?'Saved analysis. Run a new check to request a fresh AI summary.':'Optional: a reduced evidence summary is sent to OpenRouter, not file contents or email bodies.';document.querySelector('.model-label').textContent=(a.risk.model||'Historical model')+' · not CVSS';if(root?._from_history)$('mode-notice').textContent='HISTORICAL RESULT — checked on '+new Date(a.timestamp).toLocaleString('en-GB')+'. No new source lookup was performed. '+$('mode-notice').textContent;}
 function setExposure(value){document.querySelectorAll('[data-exposure]').forEach(b=>{const active=b.dataset.exposure===value;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});if(!current)return;const a=severityAdvice(current,value);$('personal-heading').textContent=a.heading;$('personal-explanation').textContent=a.message;$('personal-explanation').dataset.severity=a.band;$('personal-actions').replaceChildren(...a.steps.map((text,i)=>{const item=el('div',undefined,'personal-step');item.append(el('span',String(i+1).padStart(2,'0'),'step-index'),el('p',text));return item;}));}
