 const history=window.PhishingHistory;let historyTab='analyses',analysisRows=[],exportRows=[];
 function historyError(e){$('history-status').textContent='History could not be saved: '+(e?.message||'storage unavailable')+'. Your analysis and downloads still work.';}
 function plainReport(a){const pending=[a],seen=new Set(),lines=['ARGUSAI ANALYSIS REPORT','Saved evidence snapshot. No new provider query was performed.','Risk bands: 0–30 Low risk; 31–69 Suspicious; 70–100 Dangerous. Not a probability or CVSS.'];while(pending.length){const r=pending.shift();if(seen.has(r))continue;seen.add(r);lines.push('\nTARGET: '+r.target,'Type: '+r.kind,'Checked at: '+r.timestamp,'Score: '+(r.risk.score??'Withheld')+'/100 | '+r.risk.level,'Model: '+r.risk.model,'SHA-256: '+(r.sha256||'Not applicable'),'\nSOURCE-BY-SOURCE RESULTS');for(const p of r.providers||[]){lines.push(p.name+' | '+p.scope+' | '+p.status+' | '+p.detail+' | Checked: '+(p.checked_at||'Not supplied'));for(const e of p.engines||[])lines.push('  '+e.engine_name+' | '+e.category+' | '+(e.result||''));}lines.push('\nLOCAL CHECKS',...(r.checks||[]).map(c=>c.label+' | '+c.status+' | '+c.detail),'\nEVIDENCE',...(r.findings||[]).map(f=>f.label+' | '+f.evidence+' | +'+f.points+' once per rule'),'\nINDICATORS',...(r.links||[]).map(defang));if(r.kind==='imap')lines.push('MESSAGE HEADERS: '+JSON.stringify(r.metadata?.message||{}));lines.push('\nRECOMMENDED ACTIONS',...severityAdvice(r).steps,'\nASSESSMENT SCOPE',...(r.limitations||[]));if(r.ai_summary)lines.push('\nAI ENGLISH SUMMARY',r.ai_summary);pending.push(...(r.messages||[]),...(r.urlResults||[]),...(r.attachments||[]));}return lines.join('\n')+'\n';}
 async function persistRoot(a){if(!history.enabled())return;await history.putAnalysis(a,plainReport(a));await refreshHistory();try{const r=await fetch('/reports/'+encodeURIComponent(a.report_id)+'/download');if(r.ok){let text=await r.text();if(a.ai_summary&&!text.includes(a.ai_summary))text+='\nAI ENGLISH SUMMARY\n'+a.ai_summary;await history.putAnalysis(a,text);}}catch{/* Snapshot remains available even if the server disappears. */}}
 function drawHistory(){const search=$('history-search').value.trim().toLowerCase(),kind=$('history-kind').value;const rows=(historyTab==='analyses'?analysisRows:exportRows).filter(r=>(kind==='all'||r.kind===kind)&&(!search||(r.target+' '+(r.filename||'')).toLowerCase().includes(search)));$('history-rows').replaceChildren();$('history-empty').hidden=!!rows.length;$('history-empty').textContent=search||kind!=='all'?'No saved entries match this filter.':'No saved entries yet.';for(const r of rows){const tr=el('tr'),score=r.score===null?'—':String(r.score),band=r.score===null?'':r.score>=70?'history-risk-high':r.score>30?'history-risk-suspicious':'history-risk-low';const action=el('td');if(historyTab==='analyses'){const open=el('button','Reopen','report-btn');open.onclick=()=>restoreAnalysis(r.id);const json=el('button','JSON','report-btn');json.onclick=()=>save(JSON.stringify(r.analysis,null,2),'application/json','ArgusAI-saved-analysis.json');action.append(open,json);}else{const download=el('button','Download again','report-btn');download.onclick=()=>save(r.content,r.mime,r.filename);action.append(download);}tr.append(el('td',new Date(r.time).toLocaleString('en-GB')),el('td',r.target),el('td',historyTab==='analyses'?r.kind:r.filename.endsWith('.json')?'JSON':'TXT'),el('td',score+' · '+r.level,band),action);$('history-rows').append(tr);}}
 async function refreshHistory(){try{const [stats,analyses,exports]=await Promise.all([history.stats(),history.analyses(),history.exports()]);analysisRows=analyses;exportRows=exports;$('history-total-analyses').textContent=stats.totalAnalyses;$('history-total-exports').textContent=stats.totalExports;$('history-stored').textContent=stats.storedAnalyses+' / '+stats.storedExports;$('history-header-count').textContent=stats.totalAnalyses;drawHistory();}catch(e){historyError(e);}}
 async function restoreAnalysis(id){if(busy){$('history-status').textContent='Wait until the current check finishes before reopening a saved result.';return;}try{const saved=await history.getAnalysis(id);if(!saved)throw Error('This saved entry is no longer available.');root=structuredClone(saved.analysis);root._from_history=true;configurePicker(root);render(root);$('history-panel').hidden=true;$('preview-progress').textContent='Saved analysis reopened. No new lookup or analysis count added.';$('analysis-dashboard').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){historyError(e);}}
 $('history-open').onclick=async()=>{$('history-panel').hidden=false;await refreshHistory();$('history-panel').scrollIntoView({behavior:'smooth',block:'start'});};$('history-close').onclick=()=>$('history-panel').hidden=true;$('history-refresh').onclick=refreshHistory;
